// Build the dedupe key and normalise the input.
// Expected body: { messageId, attachmentName, fileUrl, vendorHint }
return items.map((item) => {
  const body = item.json.body || item.json;
  const messageId = String(body.messageId || '').trim();
  const attachmentName = String(body.attachmentName || 'invoice.pdf').trim();
  const fileUrl = String(body.fileUrl || '').trim();

  if (!messageId) {
    throw new Error('Missing messageId - cannot dedupe this invoice');
  }
  if (!fileUrl) {
    throw new Error('Missing fileUrl - nothing to parse');
  }

  return {
    json: {
      eventId: messageId + '::' + attachmentName,
      messageId,
      attachmentName,
      fileUrl,
      vendorHint: body.vendorHint || '',
    },
  };
});

// Parse the extraction and score how complete it is.
// confidence = filled core fields / expected core fields.
// A low score is not an error - it routes the invoice to a human.
const CORE = ['vendor', 'invoice_number', 'invoice_date', 'currency', 'total_amount'];

return items.map((item) => {
  const choice = item.json.choices && item.json.choices[0];
  const raw = choice && choice.message ? choice.message.content : '{}';

  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = {};
  }

  let filled = 0;
  for (const k of CORE) {
    const v = parsed[k];
    if (v !== null && v !== undefined && String(v).trim() !== '') filled += 1;
  }

  const source = $('Normalise Invoice').item.json;

  return {
    json: {
      eventId: source.eventId,
      confidence: Number((filled / CORE.length).toFixed(2)),
      missingFields: CORE.filter((k) => { const v = parsed[k]; return v === null || v === undefined || String(v).trim() === ''; }),
      vendor: parsed.vendor || null,
      invoiceNumber: parsed.invoice_number || null,
      invoiceDate: parsed.invoice_date || null,
      currency: parsed.currency || null,
      totalAmount: parsed.total_amount === undefined ? null : parsed.total_amount,
      lineItems: Array.isArray(parsed.line_items) ? parsed.line_items : [],
    },
  };
});

// Two jobs, both required:
//  1. Stop the run when the key is already taken. A Postgres node that gets 0 rows emits
//     { success: true } instead of an empty output, so filtering is what actually stops it.
//  2. Put the original payload back. The claim node outputs the SQL row, so without this
//     every downstream node would read fields that no longer exist.
return items
  .filter((item) => item.json && item.json.key)
  .map((item) => ({
    json: Object.assign({}, item.json.payload || {}, { claimKey: item.json.key }),
  }));
